241	
242	    /** Whether the date falls in the period, both ends inclusive. */
243	    public boolean contains(LocalDate date) {
244	        return !date.isBefore(fromDate) && !date.isAfter(toDate);
245	    }
246	
247	    /** Whether the period shares a day with the dates from and to, both inclusive. */
248	    public boolean overlaps(LocalDate from, LocalDate to) {
249	        return !fromDate.isAfter(to) && !from.isAfter(toDate);
250	    }
251	}
