272	/** Keeps the periods of each sheet: uniquely named, and no two overlapping; a closed period's claims are fixed. */
273	@Service
274	public class PeriodService {
275	
276	    private final PeriodRepository periods;
277	    private final SheetRepository sheets;
278	    private final Audit audit;
279	    private final RollupService rollup;
280	    private final RoleService roles;
281	    private final PoolCutService poolCuts;
282	
283	    public PeriodService(PeriodRepository periods, SheetRepository sheets, Audit audit, RollupService rollup,
284	            RoleService roles, PoolCutService poolCuts) {
285	        this.periods = periods;
286	        this.sheets = sheets;
287	        this.audit = audit;
288	        this.rollup = rollup;
289	        this.roles = roles;
290	        this.poolCuts = poolCuts;
291	    }
292	
293	    public List<Period> list(String sheetId) {
294	        return periods.findBySheetIdOrderByFromDateAscIdAsc(sheetId);
295	    }
296	
297	    /**
298	     * Add a period, with a cap on the OPEN or PENDING claims each person may have in it (null for none); refused when
299	     * its name is taken, its dates are reversed, its cap is below 1, or it overlaps another period.
300	     */
301	    @Transactional
302	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
303	        // Lock the sheet so two periods added at once are checked against each other.
304	        if (sheets.lockById(sheetId) == 0) {
305	            throw new SheetNotFoundException(sheetId);
306	        }
307	        if (to.isBefore(from)) {
308	            throw new PeriodRefusedException("The period " + name + " ends before it starts");
309	        }
310	        if (cap != null && cap < 1) {
311	            throw new PeriodRefusedException("The period " + name + " cannot cap claims at " + cap);
312	        }
313	        if (periods.existsBySheetIdAndName(sheetId, name)) {
314	            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
315	        }
316	        if (list(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
317	            throw new PeriodRefusedException("The period " + name + " overlaps another period on sheet " + sheetId);
318	        }
319	        Period saved;
320	        try {
321	            saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
322	        } catch (DataIntegrityViolationException e) {
323	            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
324	        }
325	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
326	                + " from=" + saved.getFromDate() + " to=" + saved.getToDate()
327	                + (saved.getCap() == null ? "" : " cap=" + saved.getCap()));
328	        return saved;
329	    }
330	
331	    /**
332	     * Generate one period per calendar month from the from-date's month to the to-date's month, each named yyyy-mm and
333	     * running from the first to the last day of its month; a month whose name is taken or whose days overlap a period
334	     * on the sheet is left out. Refused when the to-date is before the from-date. The periods made, in date order.
335	     */
336	    @Transactional
337	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
338	        if (sheets.lockById(sheetId) == 0) {
339	            throw new SheetNotFoundException(sheetId);
340	        }
341	        if (to.isBefore(from)) {
342	            throw new PeriodRefusedException("The to-date " + to + " is before the from-date " + from);
343	        }
344	        List<Period> existing = new ArrayList<>(list(sheetId));
345	        List<Period> made = new ArrayList<>();
346	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
347	            String name = month.toString();
348	            LocalDate first = month.atDay(1);
349	            LocalDate last = month.atEndOfMonth();
350	            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) {
351	                continue;
352	            }
353	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
354	            existing.add(saved);
355	            made.add(saved);
356	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
357	                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
358	        }
359	        return made;
360	    }
361	
362	    /**
363	     * Generate the twelve monthly periods of the fiscal year named FY{@code year}, from the first day of the sheet's
364	     * fiscal year start month in that year, as a generate over its dates would. The periods made, in date order.
365	     */
366	    @Transactional
367	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
368	        Sheet sheet = sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
369	        YearMonth first = YearMonth.of(year, sheet.getFiscalStartMonth());
370	        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
371	    }
372	
373	    /**
374	     * Generate the four calendar quarters of a year as periods named yyyy-Q1 to yyyy-Q4, each as the period form would
375	     * add it; a quarter whose name is taken or whose days overlap a period on the sheet is left out. The periods made,
376	     * in date order.
377	     */
378	    @Transactional
379	    public List<Period> generateQuarters(String sheetId, String user, int year) {
380	        if (sheets.lockById(sheetId) == 0) {
381	            throw new SheetNotFoundException(sheetId);
382	        }
383	        List<Period> existing = new ArrayList<>(list(sheetId));
384	        List<Period> made = new ArrayList<>();
385	        for (int quarter = 1; quarter <= 4; quarter++) {
386	            String name = year + "-Q" + quarter;
387	            YearMonth start = YearMonth.of(year, quarter * 3 - 2);
388	            LocalDate first = start.atDay(1);
389	            LocalDate last = start.plusMonths(2).atEndOfMonth();
390	            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) {
391	                continue;
392	            }
393	            Period saved = add(sheetId, user, name, first, last, null);
394	            existing.add(saved);
395	            made.add(saved);
396	        }
397	        return made;
398	    }
399	
400	    /** The name (FYyyyy) of the fiscal year a date falls in on the sheet; by a January start when there is no such sheet. */
401	    public Function<LocalDate, String> fiscalYears(String sheetId) {
402	        int startMonth = sheets.findById(sheetId).map(Sheet::getFiscalStartMonth).orElse(1);
403	        return date -> Sheet.fiscalYearOf(date, startMonth);
404	    }
405	
406	    /** Close a period, fixing every person's due-total and carried figure for it, and so its own, and every pool member's cut, as they are now; refused when it is already closed or the user's role may not close; a soft-closed period's figures are fixed afresh. */
407	    @Transactional
408	    public Period close(String sheetId, String user, String name) {
409	        // Lock the sheet so no claim in the period changes while its total is fixed.
410	        if (sheets.lockById(sheetId) == 0) {
411	            throw new SheetNotFoundException(sheetId);
412	        }
413	        Period period = periods.findBySheetIdAndName(sheetId, name)
414	                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
415	        if (!roles.may(sheetId, user, "close")) {
416	            throw new PeriodCloseForbiddenException(name, user);
417	        }
418	        if (period.isClosed()) {
419	            throw new PeriodClosedException(name);
420	        }
421	        return closeNow(sheetId, user, period, false);
422	    }
423	
424	    /**
425	     * Soft-close a period, fixing every person's due-total and carried figure for it, and so its own, and every pool member's cut, as they are now, while claims due by
426	     * a date in it can still change; refused when it is closed or soft-closed already or the user's role may not close.
427	     */
428	    @Transactional
429	    public Period softClose(String sheetId, String user, String name) {
430	        if (sheets.lockById(sheetId) == 0) {
431	            throw new SheetNotFoundException(sheetId);
432	        }
433	        Period period = periods.findBySheetIdAndName(sheetId, name)
434	                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
435	        if (!roles.may(sheetId, user, "close")) {
436	            throw new PeriodCloseForbiddenException(name, user);
437	        }
438	        if (period.isClosed() || period.isSoftClosed()) {
439	            throw new PeriodClosedException(name);
440	        }
441	        return softCloseNow(sheetId, user, period);
442	    }
443	
444	    /** Soft-close an open period as a soft close by hand would; the caller has locked the sheet and checked it is open. */
445	    Period softCloseNow(String sheetId, String user, Period period) {
446	        period.softClose(rollup.dueTotalsBetween(sheetId, period.getFromDate(), period.getToDate()),
447	                rollup.carriedInto(sheetId, list(sheetId), period), cutsNow(sheetId));
448	        Period saved = periods.saveAndFlush(period);
449	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
450	                + " total=" + saved.getClosedTotal().toPlainString());
451	        return saved;
452	    }
453	
454	    /**
455	     * Close, in order of their to-dates, every open period (neither closed nor soft-closed) whose to-date plus the
456	     * grace days is before the today, as a close by hand would, each recorded as closed automatically; none when the
457	     * grace days are off (null).
458	     */
459	    @Transactional
460	    public void autoClose(String sheetId, String user, LocalDate today, Integer graceDays) {
461	        if (graceDays == null) {
462	            return;
463	        }
464	        if (sheets.lockById(sheetId) == 0) {
465	            throw new SheetNotFoundException(sheetId);
466	        }
467	        list(sheetId).stream()
468	                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
469	                .sorted(Comparator.comparing(Period::getToDate))
470	                .forEach(p -> closeNow(sheetId, user, p, true));
471	    }
472	
473	    private Period closeNow(String sheetId, String user, Period period, boolean auto) {
474	        period.close(rollup.dueTotalsBetween(sheetId, period.getFromDate(), period.getToDate()),
475	                rollup.carriedInto(sheetId, list(sheetId), period), cutsNow(sheetId));
476	        Period saved = periods.saveAndFlush(period);
477	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
478	                + " total=" + saved.getClosedTotal().toPlainString() + (auto ? " auto=yes" : ""));
479	        return saved;
480	    }
481	
482	    /** Every pool member's cut as it stands now, to fix for a period. */
483	    private List<PeriodPoolCut> cutsNow(String sheetId) {
484	        return poolCuts.cutsNow(sheetId).stream().map(c -> new PeriodPoolCut(c.poolId(), c.member(), c.cut()))
485	                .toList();
486	    }
487	
488	    /**
489	     * Reopen a closed or soft-closed period, making its due-total and carried figures and its pool members' cuts live again; refused unless the user's role may reopen
490	     * and it is closed or soft-closed.
491	     */
492	    @Transactional
493	    public Period reopen(String sheetId, String user, String name) {
494	        if (sheets.lockById(sheetId) == 0) {
495	            throw new SheetNotFoundException(sheetId);
496	        }
497	        Period period = periods.findBySheetIdAndName(sheetId, name)
498	                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
499	        if (!roles.may(sheetId, user, "reopen")) {
500	            throw new PeriodReopenForbiddenException(name, user);
501	        }
502	        if (period.isLocked()) {
503	            throw new PeriodLockedException("The period " + name + " is locked: unlock it to reopen it");
504	        }
505	        if (!period.isClosed() && !period.isSoftClosed()) {
506	            throw new PeriodNotClosedException(name);
507	        }
508	        period.reopen();
509	        Period saved = periods.saveAndFlush(period);
510	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
511	        return saved;
512	    }
513	
514	    /** Lock or unlock a period; refused unless the user is a steward and the period is not already so. */
515	    @Transactional
516	    public Period setLocked(String sheetId, String user, String name, boolean locked) {
517	        if (sheets.lockById(sheetId) == 0) {
518	            throw new SheetNotFoundException(sheetId);
519	        }
520	        Period period = periods.findBySheetIdAndName(sheetId, name)
521	                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
522	        if (!roles.isSteward(sheetId, user)) {
523	            throw new PeriodLockForbiddenException(name, user);
524	        }
525	        if (period.isLocked() == locked) {
526	            throw new PeriodLockedException("The period " + name + (locked ? " is already locked" : " is not locked"));
527	        }
528	        period.setLocked(locked);
529	        Period saved = periods.saveAndFlush(period);
530	        audit.recordOnCommit((locked ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
531	                + " period=" + saved.getName());
532	        return saved;
533	    }
534	
535	    /** The name of the period the date falls in; empty when it is in none. */
536	    public Optional<String> nameOn(String sheetId, LocalDate date) {
537	        return list(sheetId).stream().filter(p -> p.contains(date)).map(Period::getName).findFirst();
538	    }
539	
540	    /** The period the date falls in; empty when it is in none. */
541	    public Optional<Period> on(String sheetId, LocalDate date) {
542	        return list(sheetId).stream().filter(p -> p.contains(date)).findFirst();
543	    }
544	
545	    /** Whether the date falls in a soft-closed period of the sheet. */
546	    public boolean softClosedOn(String sheetId, LocalDate date) {
547	        return list(sheetId).stream().anyMatch(p -> p.isSoftClosed() && p.contains(date));
548	    }
549	
550	    /**
551	     * Refuse a change to a claim due by any of the dates when one falls in a closed period. The sheet is locked
552	     * until the caller's transaction ends, so a period cannot close while the change is made.
553	     */
554	    @Transactional
555	    public void requireOpen(String sheetId, LocalDate... dates) {
556	        if (sheets.lockById(sheetId) == 0) {
557	            throw new SheetNotFoundException(sheetId);
558	        }
559	        for (Period period : list(sheetId)) {
560	            for (LocalDate date : dates) {
561	                if (period.isClosed() && period.contains(date)) {
562	                    throw new PeriodClosedException(period.getName(), date);
563	                }
564	            }
565	        }
566	    }
567	}
