protected readonly periods = signal<Period[]>([]);
/**
 * Each person's live due-total for each period, by person id and then period name: the dues as shown now of their
 * claims due by a date in it that were OPEN, PENDING or SETTLED at the end of its last day, skipping the n/a ones; a period they have none in is missing.
 */
private readonly livePersonPeriodDues = computed(() => {
  const byId = new Map(this.people().map((p) => [p.id, p]));
  const dues = new Map<number, Map<string, string[]>>();
  for (const c of this.claims()) {
    const period = periodOn(this.periods(), c.dueBy);
    const person = byId.get(c.personId);
    if (!period || person === undefined || !liveAtEnd(c, person, this.session.today(), period.to)) continue;
    const theirs = dues.get(person.id) ?? new Map<string, string[]>();
    const list = theirs.get(period.name) ?? [];
    list.push(claimDue(c, this.rates(), person.grades, this.session));
    theirs.set(period.name, list);
    dues.set(person.id, theirs);
  }
  return new Map(
    [...dues].map(([id, theirs]) => [id, new Map([...theirs].map(([name, list]) => [name, sumDues(list)]))]),
  );
});
/**
 * Each person's carried figure for each period, by person id and then period name: the dues as shown now of their
 * counting claims due by a date in a period ending before it starts that were OPEN or PENDING at the end of its last
 * day, skipping the n/a ones; a period with nothing carried is missing.
 */
private readonly personPeriodCarried = computed(() => {
  const byId = new Map(this.people().map((p) => [p.id, p]));
  const today = this.session.today();
  const carried = new Map<number, Map<string, string[]>>();
  for (const c of this.claims()) {
    const from = periodOn(this.periods(), c.dueBy);
    const person = byId.get(c.personId);
    if (!from || person === undefined) continue;
    for (const period of this.periods()) {
      if (from.to >= period.from || !liveAtEnd(c, person, today, period.to)) continue;
      const status = statusOn(c, period.to);
      if (status !== 'OPEN' && status !== 'PENDING') continue;
      const theirs = carried.get(person.id) ?? new Map<string, string[]>();
      const list = theirs.get(period.name) ?? [];
      list.push(claimDue(c, this.rates(), person.grades, this.session));
      theirs.set(period.name, list);
      carried.set(person.id, theirs);
    }
  }
  return new Map(
    [...carried].map(([id, theirs]) => [id, new Map([...theirs].map(([name, list]) => [name, sumDues(list)]))]),
  );
});
/** Each period's due-total by name: the sum of everyone's due-total for it. */
  if (this.rowError()?.id === id) this.rowError.set(null);
}

protected claimsOf(personId: number): Claim[] {
  return this.claimsByPerson().get(personId) ?? [];
}

/** The sum of the person's OPEN, PENDING and SETTLED claims' amounts, with two decimals, leaving out corrections; open ones once their retirement date is reached, not unless a statement binds them (a hold does not). */

/** The sheet's periods in date order. */
readonly periods = input.required<Period[]>();
/** Each period's due-total by its name: the due of the counting claims dated in it. */
readonly dueTotals = input.required<Map<string, string>>();
/** A period was added, generated, closed or reopened. */
readonly saved = output<Period>();
/** Opening balances were imported: the screen is to re-read the periods. */
readonly openingsImported = output<void>();

